for_the_developer.code:
window.dataLayer = window.dataLayer || [];
window.dataLayer.push({ecommerce: null});  // clear the previous ecommerce object
window.dataLayer.push({
  event: 'purchase',
  ecommerce: {
    transaction_id: order.id,       // the app's order id, e.g. 'ord_10482'
    value: order.total,             // e.g. 49.00 for the Growth plan
    currency: order.currency,       // e.g. 'USD'
    items: [{item_id: order.planId, item_name: order.planName, price: order.total, quantity: 1}]
  }
});
